package com.youngone.mediacontrol.agent.api;
import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.http.MediaType;import org.springframework.test.web.servlet.MockMvc;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties="youngone.agent.bootstrap-token=test-bootstrap")@AutoConfigureMockMvc class AgentApiIntegrationTest{
 @Autowired MockMvc mvc;private String registration(String installation,String evidence,String boot){return "{\"bootstrapToken\":\"test-bootstrap\",\"installationId\":\""+installation+"\",\"hostname\":\"pc1\",\"agentVersion\":\"1\",\"osVersion\":\"win\",\"environmentType\":\"PHYSICAL\",\"deviceEvidenceHash\":\""+evidence+"\",\"bootSessionId\":\""+boot+"\"}";}
 @Test void registerAuthenticateAndDeduplicateHeartbeat()throws Exception{String response=mvc.perform(post("/api/v1/agents/register").contentType(MediaType.APPLICATION_JSON).content(registration("api-i1","evidence-a","boot-1"))).andExpect(status().isCreated()).andExpect(jsonPath("$.identityDisposition").value("NEW")).andReturn().getResponse().getContentAsString();String id=response.replaceAll(".*\\\"agentId\\\":\\\"([^\\\"]+).*","$1"),key=response.replaceAll(".*\\\"agentKey\\\":\\\"([^\\\"]+).*","$1");String hb="{\"eventId\":\"evt-1\",\"agentVersion\":\"1\",\"osVersion\":\"win\",\"queueDepth\":0}";mvc.perform(post("/api/v1/agents/"+id+"/heartbeat").header("X-Agent-Key",key).contentType(MediaType.APPLICATION_JSON).content(hb)).andExpect(status().isOk()).andExpect(jsonPath("$.duplicate").value(false));mvc.perform(post("/api/v1/agents/"+id+"/heartbeat").header("X-Agent-Key",key).contentType(MediaType.APPLICATION_JSON).content(hb)).andExpect(status().isOk()).andExpect(jsonPath("$.duplicate").value(true));}
 @Test void sameInstallationWithDifferentEvidenceIsRejected()throws Exception{mvc.perform(post("/api/v1/agents/register").contentType(MediaType.APPLICATION_JSON).content(registration("clone-i1","evidence-original","boot-a"))).andExpect(status().isCreated());mvc.perform(post("/api/v1/agents/register").contentType(MediaType.APPLICATION_JSON).content(registration("clone-i1","evidence-clone","boot-b"))).andExpect(status().isConflict()).andExpect(jsonPath("$.securityStatus").value("DUPLICATE_SUSPECTED")).andExpect(jsonPath("$.agentKey").doesNotExist());}
}
